t.script:
(function () {
  function fmt(v){try{return (v).toLocaleString(undefined,{minimumFractionDigits:3,maximumFractionDigits:3})}catch(e){return v}}
  const input = document.getElementById("pcfp-input");
  input.addEventListener("keydown", function(ev){
    if(ev.key==="Enter"){
      ev.preventDefault();
      const code = input.value.trim();
      if(!code){return;}
      input.select();
      odoo.jsonRpc("/price_check/api/lookup","call",{barcode:code}).then(function(resp){
        if(!resp || !resp.ok){document.getElementById("pcfp-name").textContent="—";return;}
        document.getElementById("pcfp-name").textContent = resp.name || "—";
        document.getElementById("pcfp-left-title").textContent = resp.left_title || "—";
        document.getElementById("pcfp-left-value").textContent = (fmt(resp.left_value) + " " + (resp.currency||"")).trim();
        if(resp.right_value!=null){
          document.getElementById("pcfp-right-col").style.display="block";
          document.getElementById("pcfp-right-title").textContent = resp.right_title || "—";
          document.getElementById("pcfp-right-value").textContent = (fmt(resp.right_value) + " " + (resp.currency||"")).trim();
        }else{
          document.getElementById("pcfp-right-col").style.display="none";
        }
      });
    }
  });
})();
